// transformData converts API response data to the format required by the database
func transformData(apiData []APIResponse) []DatabaseModel {
	var dbModels []DatabaseModel

	for _, item := range apiData {
		dbModel := DatabaseModel{
			ID:          bson.NewObjectId(),
			Name:        item.Name,
			Description: item.Description,
		}
