}

// storeDataInMongoDB stores the transformed data in MongoDB
func storeDataInMongoDB(data []DatabaseModel) error {
	// Connect to MongoDB
	session, err := mgo.Dial(MongoURI)
	if err != nil {
		return errors.Trace(err)
	}
	defer session.Close()

	// Get the database and collection
	collection := session.DB(DBName).C(Collection)

	// Insert data into the collection
	for _, item := range data {
		// Check if the item already exists to prevent duplicates
		exists, err := doesItemExist(collection, item.Name)
		if err != nil {
			return errors.Trace(err)
		}

		// Only insert if the item doesn't already exist
		if !exists {
			if err := collection.Insert(item); err != nil {
				return errors.Trace(err)
			}
		}
	}

	return nil
}

