import android.os.Bundle;
import android.os.Environment;
import android.provider.MediaStore;
import android.util.Log;
import android.widget.Toast;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CameraFilterActivity extends Activity {

    private static final int REQUEST_IMAGE_CAPTURE = 1;
    private String imagePath;
    private ExecutorService executorService;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_camera_filter);

        executorService = Executors.newSingleThreadExecutor();

        // Launch camera intent
        Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
        if (intent.resolveActivity(getPackageManager()) != null) {
            File photoFile = null;
            try {
                photoFile = createImageFile();
            } catch (IOException ex) {
                // Error occurred while creating the File
                Log.e("CameraFilterActivity", "Error creating image file", ex);
            }
            if (photoFile != null) {
                Uri photoURI = Uri.fromFile(photoFile);
                intent.putExtra(MediaStore.EXTRA_OUTPUT, photoURI);
                imagePath = photoFile.getAbsolutePath();
                startActivityForResult(intent, REQUEST_IMAGE_CAPTURE);
            } else {
                Toast.makeText(this, "Failed to create image file", Toast.LENGTH_SHORT).show();
            }
        } else {
            Toast.makeText(this, "No camera app available", Toast.LENGTH_SHORT).show();
        }
    }

    private File createImageFile() throws IOException {
        String timeStamp = new java.text.SimpleDateFormat("yyyyMMdd_HHmmss").format(new java.util.Date());
        String imageFileName = "JPEG_" + timeStamp + "_";
        File storageDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES);
        return File.createTempFile(imageFileName, ".jpg", storageDir);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQUEST_IMAGE_CAPTURE && resultCode == RESULT_OK) {
            applyFiltersAndSaveImage();
        } else {
            Toast.makeText(this, "Image capture failed", Toast.LENGTH_SHORT).show();
        }
    }

    private void applyFiltersAndSaveImage() {
        executorService.execute(() -> {
            try {
                // Load the captured image
                Bitmap originalBitmap = BitmapFactory.decodeFile(imagePath);
                if (originalBitmap == null) {
                    throw new IOException("Failed to load image");
                }

                // Apply filters
                Bitmap processedBitmap = applyBrightness(originalBitmap, 30);
                processedBitmap = applyContrast(processedBitmap, 1.5f);
                processedBitmap = applyColorBalance(processedBitmap, 0.2f, 0.1f, 0.1f);

                // Save the processed image
                saveImageToStorage(processedBitmap);
                runOnUiThread(() -> Toast.makeText(this, "Image processed and saved", Toast.LENGTH_SHORT).show());
            } catch (Exception e) {
                Log.e("CameraFilterActivity", "Error processing image", e);
                runOnUiThread(() -> Toast.makeText(this, "Image processing failed", Toast.LENGTH_SHORT).show());
            } finally {
                // Recycle the bitmaps to free up memory
                if (originalBitmap != null) originalBitmap.recycle();
                if (processedBitmap != null) processedBitmap.recycle();
            }
        });
    }

    private Bitmap applyBrightness(Bitmap bitmap, float brightness) {
        ColorMatrix colorMatrix = new ColorMatrix();
        colorMatrix.setScale(1, 1, 1, brightness);
        Paint paint = new Paint();
        paint.setColorFilter(new ColorMatrixColorFilter(colorMatrix));
        Bitmap result = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(result);
        canvas.drawBitmap(bitmap, 0, 0, paint);
        return result;
    }

    private Bitmap applyContrast(Bitmap bitmap, float contrast) {
        ColorMatrix colorMatrix = new ColorMatrix();
        colorMatrix.setScale(contrast, contrast, contrast, 1);
        Paint paint = new Paint();
        paint.setColorFilter(new ColorMatrixColorFilter(colorMatrix));
        Bitmap result = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(result);
        canvas.drawBitmap(bitmap, 0, 0, paint);
        return result;
    }

    private Bitmap applyColorBalance(Bitmap bitmap, float red, float green, float blue) {
        ColorMatrix colorMatrix = new ColorMatrix();
        colorMatrix.postConcat(new ColorMatrix(new float[]{
                red, 0, 0, 0, 0,
                0, green, 0, 0, 0,
                0, 0, blue, 0, 0,
                0, 0, 0, 1, 0
        }));
        Paint paint = new Paint();
        paint.setColorFilter(new ColorMatrixColorFilter(colorMatrix));
        Bitmap result = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(result);
        canvas.drawBitmap(bitmap, 0, 0, paint);
        return result;
    }

    private void saveImageToStorage(Bitmap bitmap) {
        String fileName = "Processed_" + System.currentTimeMillis() + ".jpg";
        File storageDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES);
        File imageFile = new File(storageDir, fileName);

        try {
            FileOutputStream fos = new FileOutputStream(imageFile);
            bitmap.compress(Bitmap.CompressFormat.JPEG, 100, fos);
            fos.flush();
            fos.close();

            // Notify the system that a new image has been saved
            Intent mediaScanIntent = new Intent(Intent.ACTION_MEDIA_SCANNER_SCAN_FILE);
            Uri contentUri = Uri.fromFile(imageFile);
            mediaScanIntent.setData(contentUri);
            sendBroadcast(mediaScanIntent);
        } catch (IOException e) {
            Log.e("CameraFilterActivity", "Error saving image", e);
        } finally {
            if (bitmap != null) bitmap.recycle();
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (executorService != null) {
            executorService.shutdown();
        }
    }
}
```

### Explanation:

1. **Camera Intent**: We create an intent to launch the camera app and capture an image. The image is saved to a temporary file.

2. **Image Processing**: We use the `Bitmap` class to load the captured image and apply filters using `ColorMatrix` and `Canvas`. The filters are applied sequentially.

3. **Saving the Image**: After processing, the image is saved to the device's storage using `FileOutputStream`.

4. **Error Handling**: We handle cases where the camera is not available or the image processing fails by catching exceptions and displaying appropriate messages.

5. **Optimization**: Although the filters are applied sequentially, we use a single-threaded executor to manage the processing. For larger images, consider using parallel processing with `ExecutorService` or `Parallel Streams`.

### Notes:

- **Permissions**: Ensure that you have the necessary permissions in your `AndroidManifest.xml` for writing to external storage and accessing the camera.
- **Memory Management**: Recycle bitmaps after they are no longer needed to free up memory.
- **User Interface**: The `runOnUiThread` method is used to update the UI from the background thread.

