// bayesian_inference.rs
use std::collections::HashMap;
use std::time::SystemTime;

#[derive(Debug, Clone)]
pub struct BayesianModel {
    // Bayesian network parameters
    pub nodes: HashMap<String, f64>,
    pub edges: HashMap<String, Vec<String>>,
    pub prior_probabilities: HashMap<String, f64>,
    pub conditional_probabilities: HashMap<String, HashMap<String, f64>>,
}

impl BayesianModel {
    pub fn new() -> Self {
        BayesianModel {
            nodes: HashMap::new(),
            edges: HashMap::new(),
            prior_probabilities: HashMap::new(),
            conditional_probabilities: HashMap::new(),
        }
    }

    pub fn add_node(&mut self, node: &str, probability: f64) {
        self.nodes.insert(node.to_string(), probability);
        self.prior_probabilities.insert(node.to_string(), probability);
    }

    pub fn add_edge(&mut self, from: &str, to: &str) {
        self.edges.entry(from.to_string()).or_insert_with(Vec::new).push(to.to_string());
    }

    pub fn update_probability(&mut self, node: &str, probability: f64) {
        if let Some(prob) = self.nodes.get_mut(node) {
            *prob = probability;
        }
    }

    pub fn calculate_posterior(&self, evidence: &HashMap<String, f64>) -> HashMap<String, f64> {
        let mut posterior = HashMap::new();
        for (node, _) in &self.nodes {
            let mut posterior_prob = 1.0;
            for (parent, _) in &self.edges {
                if let Some(evidence_value) = evidence.get(parent) {
                    posterior_prob *= self.conditional_probabilities
                        .get(parent)
                        .and_then(|cp| cp.get(node))
                        .unwrap_or(&1.0)
                        * evidence_value;
                }
            }
            posterior.insert(node.clone(), posterior_prob);
        }
        posterior
    }
}
